import{_ as o,o as a,c as n,a2 as t}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/es/fontes-detalhe.png",r="/pro-agent-hub-installer/capturas/es/conhecimento-detalhe.png",h=JSON.parse('{"title":"Conocimiento y fuentes de datos","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/conhecimento.md","filePath":"es/interface/conhecimento.md","lastUpdated":1787856241000}'),i={name:"es/interface/conhecimento.md"};function c(l,e,d,p,u,m){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="conocimiento-y-fuentes-de-datos" tabindex="-1">Conocimiento y fuentes de datos <a class="header-anchor" href="#conocimiento-y-fuentes-de-datos" aria-label="Permalink to &quot;Conocimiento y fuentes de datos&quot;">​</a></h1><p>Un agente sabe lo que aprendió el modelo, y nada más. <strong>Conocimiento</strong> es cómo se le da lo que sabe tu empresa.</p><p>Son dos piezas, y el orden importa: la <strong>fuente de datos</strong> dice de dónde viene el contenido; el <strong>conocimiento</strong> convierte ese contenido en vectores que el agente consulta.</p><h2 id="fuentes-de-datos" tabindex="-1">Fuentes de datos <a class="header-anchor" href="#fuentes-de-datos" aria-label="Permalink to &quot;Fuentes de datos&quot;">​</a></h2><p><img src="'+s+'" alt="fontes-detalhe"></p><p>Hay tres tipos, y la pantalla cambia según el elegido:</p><p><strong>Base de datos (SQL).</strong> Una conexión registrada más una consulta. Cada fila del resultado se convierte en un documento.</p><p><strong>Carpeta de archivos.</strong> Un directorio del servidor, opcionalmente recursivo, con filtro por extensión. Lee <code>pdf</code>, <code>docx</code>, <code>txt</code>, <code>csv</code>, entre otros.</p><p><strong>Sitio web (web scraping).</strong> Una URL y <strong>selectores CSS</strong> que dicen qué trozo de la página es qué campo. Las cabeceras HTTP son opcionales — el <code>User-Agent</code> ya viene rellenado, porque sin él muchos sitios rechazan la conexión.</p><div class="tip custom-block"><p class="custom-block-title">¿No sabes los selectores?</p><p>El botón <strong>Sugerir</strong> activa Pegasus: busca el HTML real de la página y propone los selectores. Es el paso que nadie adivina sin abrir el inspector del navegador. Exige Pegasus habilitado en Configuración.</p></div><div class="warning custom-block"><p class="custom-block-title">Las páginas que montan el contenido en JavaScript quedan fuera</p><p>La captura lee el HTML servido, sin navegador. Si el contenido solo aparece después de que corra el JavaScript, los selectores no encuentran nada. Es el canje aceptado para no cargar un Chromium dentro del contenedor.</p></div><p>La captura tiene topes propios — tiempo total, tamaño del cuerpo, número de redirecciones y 5.000 filas. Un sitio es de un tercero: sin topes, una página lenta o enorme dejaría el proceso atrapado.</p><p><strong>Probar</strong> ejecuta la recolección y muestra lo que vino, sin grabar nada. Úsalo antes de vincularla a un conocimiento.</p><h2 id="conocimiento" tabindex="-1">Conocimiento <a class="header-anchor" href="#conocimiento" aria-label="Permalink to &quot;Conocimiento&quot;">​</a></h2><p><img src="'+r+'" alt="conhecimento-detalhe"></p><p>Un conocimiento apunta a una fuente de datos y a un <strong>modelo de embedding</strong>, y produce una colección de vectores.</p><h3 id="pestana-procesamiento" tabindex="-1">Pestaña Procesamiento <a class="header-anchor" href="#pestana-procesamiento" aria-label="Permalink to &quot;Pestaña Procesamiento&quot;">​</a></h3><p>Aquí están los parámetros de la vectorización:</p><ul><li><strong>Tamaño y solapamiento del bloque</strong> — los documentos más grandes que el bloque se dividen; el solapamiento evita cortar una frase por la mitad entre dos bloques.</li><li><strong>Tamaño del lote</strong> — cuántos documentos van a la vez al modelo de embedding.</li><li><strong>Máximo de resultados en la búsqueda</strong> — cuántos fragmentos recibe el agente por pregunta.</li><li><strong>Expresión cron</strong> — para revectorizar solo, cada cierto tiempo.</li></ul><p>Y tres campos de código Python, que valen para la fuente <strong>SQL</strong>:</p><ul><li><strong>Declaración del pipeline</strong> — corre una vez, antes de la ingesta. Ahí van los <code>import</code>, las funciones auxiliares y los acumuladores.</li><li><strong>Contenido del documento</strong> — una expresión que devuelve el texto a vectorizar.</li><li><strong>Metadatos del documento</strong> — una expresión que devuelve un diccionario.</li></ul><div class="warning custom-block"><p class="custom-block-title">Estas expresiones corren en un ámbito vacío</p><p>Ninguna función de la plataforma existe ahí. Lo que tienes es <code>row</code>, la fila actual de la consulta, y lo que tú mismo definiste en la Declaración del pipeline. Ver <a href="/pro-agent-hub-installer/es/funcoes/conhecimento_pipeline">Conocimiento — expresiones del pipeline</a>.</p></div><h3 id="carga-completa" tabindex="-1">Carga completa <a class="header-anchor" href="#carga-completa" aria-label="Permalink to &quot;Carga completa&quot;">​</a></h3><p>La recarga completa <strong>borra la colección y la recrea</strong>. Es lo que quieres cuando cambiaste el modelo de embedding (cambia la dimensión) o cuando se eliminaron registros en el origen y quedaron vectores obsoletos. Una carga normal solo añade lo que cambió.</p>',24)])])}const b=o(i,[["render",c]]);export{h as __pageData,b as default};
